'use client';

import { useEffect } from 'react';
import AnalyticsDashboard from '../components/dashboard/AnalyticsDashboard';
import DprEntryForm from '../components/dpr/DprEntryForm';
import HistoryScreen from '../components/history/HistoryScreen';
import MaterialsScreen from '../components/materials/MaterialsScreen';

export default function Page() {
  useEffect(() => {
    if (typeof window === 'undefined') return;

    // -- Inject jsPDF (+autotable) and SheetJS from CDN for the legacy Master Log exports --
    // (per-DPR JPG/PDF use the bundled html2canvas/jspdf in lib/report/exportReport.js)
    const s2 = document.createElement('script');
    s2.src = 'https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js';
    document.head.appendChild(s2);

    const s3 = document.createElement('script');
    s3.src = 'https://cdn.sheetjs.com/xlsx-0.20.2/package/dist/xlsx.full.min.js';
    document.head.appendChild(s3);

    const s4 = document.createElement('script');
    s4.src = 'https://cdnjs.cloudflare.com/ajax/libs/jspdf-autotable/3.8.2/jspdf.plugin.autotable.min.js';
    s2.onload = () => document.head.appendChild(s4);

    // -- Render HTML into container --
    const container = document.getElementById('__dpr_root__');
    if (container) {
      container.innerHTML = "<!-- ── LOGIN ─────────────────────────────────────────────────── -->\n<div id=\"loginOverlay\">\n    <div class=\"login-box\">\n        <div class=\"login-logo\">📋 DPR — Man Power Report</div>\n        <div class=\"login-sub\">Trimandir Construction Project</div>\n        <label style=\"text-align:left;\">Username</label>\n        <input type=\"text\" id=\"loginName\" placeholder=\"Enter username\" autocapitalize=\"none\" autocorrect=\"off\" autocomplete=\"username\">\n        <label style=\"text-align:left;\">Password</label>\n        <input type=\"password\" id=\"loginPass\" placeholder=\"Enter password\" autocapitalize=\"none\" autocorrect=\"off\"\n               onkeydown=\"if(event.key==='Enter')doLogin()\" autocomplete=\"current-password\">\n        <button class=\"btn-green\" onclick=\"doLogin()\" style=\"margin-top:6px;\">Sign In &#8594;</button>\n        <div class=\"login-err\" id=\"loginErr\"></div>\n        <div style=\"font-size: 12px; color: var(--muted); margin-top: 16px; text-align: center;\">Please sign in to continue</div>\n    </div>\n    <div style=\"text-align:center;\">\n        <div style=\"color:rgba(255,255,255,.55);font-size:11px;margin-bottom:8px;\">— Quick Select —</div>\n        <div class=\"user-chips\" id=\"userChips\"></div>\n    </div>\n</div>\n\n<div class=\"app-shell\">\n\n<!-- ── HEADER ─────────────────────────────────────────────────── -->\n<div class=\"header-wrap\">\n    <div>\n        <div class=\"logo\">&#128203; MAN POWER REPORT</div>\n        <div class=\"sub\">Trimandir Construction Project</div>\n    </div>\n    <div class=\"header-right\">\n        <div class=\"header-user\" id=\"headerUser\"></div>\n        <div style=\"display:flex;gap:6px;justify-content:flex-end;\">\n            <button class=\"btn-theme\" onclick=\"toggleTheme()\" id=\"themeToggleBtn\" aria-label=\"Toggle dark mode\" title=\"Toggle dark mode\">&#127769;</button>\n            <button class=\"btn-signout\" onclick=\"doLogout()\">Sign Out</button>\n        </div>\n    </div>\n</div>\n\n<div id=\"offlineBadge\">&#9888;&#65039; Offline Mode — data will sync on reconnect</div>\n\n<!-- ── TABS ──────────────────────────────────────────────────── -->\n<div class=\"tab-bar\">\n    <button class=\"tab-btn active\" id=\"tabBtnForm\"      onclick=\"resetAndSwitchToForm(this)\">&#128221; New DPR</button>\n    <button class=\"tab-btn\"        id=\"tabBtnHistory\"   onclick=\"switchTab('History',this)\">&#128194; History</button>\n    <button class=\"tab-btn\"        id=\"tabBtnDashboard\" onclick=\"switchTab('Dashboard',this)\">&#128202; Dashboard</button>\n    <button class=\"tab-btn\"        id=\"tabBtnMaterials\" onclick=\"switchTab('Materials',this)\">&#128230; Material Consumption</button>\n    <button class=\"tab-btn\"        id=\"adminTabBtn\"     onclick=\"switchTab('Admin',this)\" style=\"display:none;\">&#9881;&#65039; Admin</button>\n</div>\n\n<!-- ═══════════════════════════════════════════════════════════════\n     NEW DPR FORM\n═══════════════════════════════════════════════════════════════ -->\n<div class=\"tab-page active\" id=\"tabForm\">\n    <!-- React: components/dpr/DprEntryForm.jsx, portal-mounted here -->\n    <div id=\"__entry_mount__\"></div>\n\n</div>\n\n<!-- ═══════════════════════════════════════════════════════════════\n     HISTORY TAB\n═══════════════════════════════════════════════════════════════ -->\n<div class=\"tab-page\" id=\"tabHistory\" style=\"display:none;\">\n    <!-- React: components/history/HistoryScreen.jsx, portal-mounted here -->\n    <div id=\"__history_mount__\"></div>\n</div>\n\n<!-- ═══════════════════════════════════════════════════════════════\n     DASHBOARD TAB\n═══════════════════════════════════════════════════════════════ -->\n<div class=\"tab-page\" id=\"tabDashboard\" style=\"display:none;\">\n    <div id=\"__dashboard_mount__\"></div>\n</div>\n\n<!-- ═══════════════════════════════════════════════════════════════\n     MATERIAL CONSUMPTION TAB\n═══════════════════════════════════════════════════════════════ -->\n<div class=\"tab-page\" id=\"tabMaterials\" style=\"display:none;\">\n    <!-- React: components/materials/MaterialsScreen.jsx, portal-mounted here -->\n    <div id=\"__materials_mount__\"></div>\n</div>\n\n<!-- ═══════════════════════════════════════════════════════════════\n     ADMIN TAB\n═══════════════════════════════════════════════════════════════ -->\n<div class=\"tab-page\" id=\"tabAdmin\" style=\"display:none;\">\n\n    <!-- Analytics Dashboard -->\n    <div class=\"card\" style=\"margin-bottom:12px;\">\n        <div class=\"section-title\">📊 Admin Analytics Dashboard</div>\n        <div class=\"dash-grid\" style=\"grid-template-columns: repeat(auto-fit, minmax(100px, 1fr)); gap: 10px; margin-bottom: 12px;\">\n            <div class=\"dash-stat\" style=\"padding: 12px 8px;\">\n                <div class=\"num\" id=\"adminWorkforceToday\" style=\"font-size: 24px;\">0</div>\n                <div class=\"lbl\">Workforce Today</div>\n            </div>\n            <div class=\"dash-stat\" style=\"padding: 12px 8px;\">\n                <div class=\"num\" id=\"adminActiveSite\" style=\"font-size: 14px; word-break: break-all; height: 32px; display: flex; align-items: center; justify-content: center; font-weight:700;\">—</div>\n                <div class=\"lbl\">Most Active Site</div>\n            </div>\n            <div class=\"dash-stat\" style=\"padding: 12px 8px;\">\n                <div class=\"num\" id=\"adminProjectRatio\" style=\"font-size: 24px;\">0/0</div>\n                <div class=\"lbl\">Active Projects</div>\n            </div>\n        </div>\n        <div class=\"btn-group\" style=\"margin-top: 4px; grid-template-columns: repeat(3, 1fr);\">\n            <button class=\"btn-green btn-sm\" style=\"display: flex; align-items: center; justify-content: center; gap: 6px; font-size:12px;\" onclick=\"exportMasterLogCSV()\">\n                📥 CSV\n            </button>\n            <button class=\"btn-green btn-sm\" style=\"display: flex; align-items: center; justify-content: center; gap: 6px; font-size:12px;\" onclick=\"exportMasterLogExcel()\">\n                📊 Excel\n            </button>\n            <button class=\"btn-green btn-sm\" style=\"display: flex; align-items: center; justify-content: center; gap: 6px; font-size:12px;\" onclick=\"exportMasterLogPDF()\">\n                📄 PDF\n            </button>\n        </div>\n    </div>\n\n    <!-- Pending edit requests -->\n    <div class=\"card\" style=\"margin-bottom:12px;\">\n        <div class=\"section-title\">&#9998;&#65039; Pending Edit Requests</div>\n        <div id=\"pendingEditRequests\"><p style=\"color:var(--muted);font-size:13px;text-align:center;padding:10px;\">&#9989; No pending requests.</p></div>\n    </div>\n\n    <!-- Users -->\n    <div class=\"admin-acc-card\">\n        <div class=\"admin-acc-header\"\n             onclick=\"this.nextElementSibling.classList.toggle('open');this.querySelector('.aci').textContent=this.nextElementSibling.classList.contains('open')?'&#9660;':'&#9654;';\">\n            <span>&#9881;&#65039; Create / Manage Users</span><span class=\"aci admin-acc-icon\">&#9654;</span>\n        </div>\n        <div class=\"admin-acc-body open\">\n            <div style=\"background:#f8fafc;border:1.5px solid var(--border);border-radius:8px;padding:14px;margin-bottom:14px;\">\n                <div style=\"font-weight:700;font-size:14px;color:var(--primary);margin-bottom:10px;\">&#10133; Create New User</div>\n                <label>Username</label>\n                <input type=\"text\" id=\"newUsername\" placeholder=\"e.g. site-manager-01\">\n                <label>Display Name</label>\n                <input type=\"text\" id=\"newDisplayName\" placeholder=\"e.g. Ramesh Patel\">\n                <label>Password</label>\n                <input type=\"text\" id=\"newPassword\" placeholder=\"Set a password\">\n                <label>Role</label>\n                <select id=\"newRole\">\n                    <option value=\"user\">User — Can create &amp; view DPRs</option>\n                    <option value=\"admin\">Admin — Full access + Management</option>\n                </select>\n                <button class=\"btn-green\" onclick=\"createUser()\">&#9989; Create User</button>\n            </div>\n            <div style=\"font-weight:700;font-size:14px;color:var(--primary);margin-bottom:4px;\">&#128101; All Users</div>\n            <div class=\"admin-list-scroll\" id=\"adminUserList\"></div>\n        </div>\n    </div>\n\n    <!-- Projects -->\n    <div class=\"admin-acc-card\">\n        <div class=\"admin-acc-header\"\n             onclick=\"this.nextElementSibling.classList.toggle('open');this.querySelector('.aci').textContent=this.nextElementSibling.classList.contains('open')?'&#9660;':'&#9654;';\">\n            <span>&#128205; Manage Projects &amp; Sub-Projects</span><span class=\"aci admin-acc-icon\">&#9654;</span>\n        </div>\n        <div class=\"admin-acc-body\">\n            <p style=\"font-size:13px;color:var(--muted);margin-bottom:14px;\">\n                Only <b>active</b> projects appear in the DPR form.\n            </p>\n            <div style=\"background:#f8fafc;border:1.5px solid var(--border);border-radius:8px;padding:14px;margin-bottom:14px;\">\n                <div style=\"font-weight:700;font-size:14px;color:var(--primary);margin-bottom:10px;\">&#10133; Add Project</div>\n                <label>Parent Project (blank = top-level)</label>\n                <select id=\"newProjectParent\"><option value=\"\">— None (Top-level) —</option></select>\n                <label>Project Name</label>\n                <input type=\"text\" id=\"newProjectName\" placeholder=\"e.g. New Hospital Wing\">\n                <button class=\"btn-green\" onclick=\"adminAddProject()\">&#9989; Add Project</button>\n            </div>\n            <div style=\"font-weight:700;font-size:14px;color:var(--primary);margin-bottom:4px;\">&#128203; All Projects</div>\n            <div class=\"admin-list-scroll\" style=\"max-height:360px;\" id=\"adminProjectList\">\n                <p style=\"color:var(--muted);font-size:13px;text-align:center;padding:12px;\">Loading...</p>\n            </div>\n        </div>\n    </div>\n\n    <!-- Activities -->\n    <div class=\"admin-acc-card\">\n        <div class=\"admin-acc-header\"\n             onclick=\"this.nextElementSibling.classList.toggle('open');this.querySelector('.aci').textContent=this.nextElementSibling.classList.contains('open')?'&#9660;':'&#9654;';\">\n            <span>&#128203; Manage Activities &amp; Sub-Activities</span><span class=\"aci admin-acc-icon\">&#9654;</span>\n        </div>\n        <div class=\"admin-acc-body\">\n            <p style=\"font-size:13px;color:var(--muted);margin-bottom:14px;\">\n                Main Activities = work categories (e.g. RCC Work). Sub-Activities = specific tasks (e.g. Steel work).\n                Selecting a Main Activity dynamically loads its Sub-Activities in the form.\n            </p>\n            <div style=\"background:#f8fafc;border:1.5px solid var(--border);border-radius:8px;padding:14px;margin-bottom:12px;\">\n                <div style=\"font-weight:700;font-size:14px;color:var(--primary);margin-bottom:10px;\">&#10133; Add Main Activity</div>\n                <label>Category Name</label>\n                <input type=\"text\" id=\"newMainActivityName\" placeholder=\"e.g. MEP Work\">\n                <button class=\"btn-green\" onclick=\"adminAddMainActivity()\">&#9989; Add Category</button>\n            </div>\n            <div style=\"background:#f8fafc;border:1.5px solid var(--border);border-radius:8px;padding:14px;margin-bottom:14px;\">\n                <div style=\"font-weight:700;font-size:14px;color:var(--primary);margin-bottom:10px;\">&#10133; Add Sub-Activity</div>\n                <label>Parent Main Activity</label>\n                <select id=\"subActivityParent\"><option value=\"\">— Select Main Activity —</option></select>\n                <label>Sub-Activity Name</label>\n                <input type=\"text\" id=\"newSubActivityName\" placeholder=\"e.g. Panel Wiring\">\n                <button class=\"btn-green\" onclick=\"adminAddSubActivity()\">&#9989; Add Sub-Activity</button>\n            </div>\n            <div style=\"font-weight:700;font-size:14px;color:var(--primary);margin-bottom:4px;\">&#128202; All Activities</div>\n            <div class=\"admin-list-scroll\" style=\"max-height:480px;\" id=\"adminActivityList\">\n                <p style=\"color:var(--muted);font-size:13px;text-align:center;padding:12px;\">Loading...</p>\n            </div>\n        </div>\n    </div>\n\n    <div class=\"admin-acc-card\">\n        <div class=\"admin-acc-header\"\n             onclick=\"this.nextElementSibling.classList.toggle('open');this.querySelector('.aci').textContent=this.nextElementSibling.classList.contains('open')?'&#9660;':'&#9654;';\">\n            <span>&#129521; Manage Materials</span><span class=\"aci admin-acc-icon\">&#9654;</span>\n        </div>\n        <div class=\"admin-acc-body\">\n            <p style=\"font-size:13px;color:var(--muted);margin-bottom:14px;\">\n                The materials offered when logging consumption entries. The unit is only a default — each entry records its own unit.\n            </p>\n            <div style=\"background:var(--surface-subtle);border:1.5px solid var(--border);border-radius:8px;padding:14px;margin-bottom:14px;\">\n                <div style=\"font-weight:700;font-size:14px;color:var(--primary);margin-bottom:10px;\">&#10133; Add Material</div>\n                <label>Material Name</label>\n                <input type=\"text\" id=\"newMaterialName\" placeholder=\"e.g. Cement\">\n                <label>Default Unit <span style=\"font-weight:400;text-transform:none;\">(Optional)</span></label>\n                <input type=\"text\" id=\"newMaterialUnit\" placeholder=\"e.g. Bags, Nos, Brass, Kg\">\n                <button class=\"btn-green\" onclick=\"adminAddMaterial()\">&#9989; Add Material</button>\n            </div>\n            <div style=\"font-weight:700;font-size:14px;color:var(--primary);margin-bottom:4px;\">&#128202; All Materials</div>\n            <div class=\"admin-list-scroll\" style=\"max-height:480px;\" id=\"adminMaterialList\">\n                <p style=\"color:var(--muted);font-size:13px;text-align:center;padding:12px;\">Loading...</p>\n            </div>\n        </div>\n    </div>\n</div>\n\n<div id=\"toast\"></div>\n<footer>&#169; 2026 Trimandir Construction Project &nbsp;|&nbsp; Trimandir Site DPR</footer>\n\n</div>";
    }

    // -- Inject all app logic as a live script element --
    const appScript = document.createElement('script');
    appScript.textContent = "/* ═══════════════════════════════════════════════════════════\n           CONSTANTS & STATE\n        ═══════════════════════════════════════════════════════════ */\n        const SHEET_URL = \"/api/proxy\";\n        const SUPER_ADMIN = { username: 'TPD-admin', displayName: 'TPD Admin', role: 'admin' };\n\n        let _users      = [SUPER_ADMIN];\n        let _projects   = [];   // { id, project_name, parent_id, status } (synced with 5-column nested Projects/Activities database)\n        let _activities = [];   // { id, activity_name, parent_id, status } (synced with 5-column nested schema)\n        let _materials  = [];   // { id, material_name, unit, status }\n        let _history    = [];   // see handleGetDPRs schema below\n        let _materialLogs = []; // { date, site, material_name, qty, unit, loggedBy, createdAt } — see Material_Logs sheet\n        let _materialLogsStatus = 'idle'; // 'idle' | 'loading' | 'ok' | 'error' — read by MaterialsScreen\n        let _currentUser    = null;\n\n        function conditionEmoji(val) {\n            const map = { 'Sunny': '☀️', 'Rainy': '🌧️', 'Cloudy': '☁️', 'Site Closed': '🚧', 'Holiday': '🎉' };\n            return map[val] || '';\n        }\n\n        let _historyStatus = 'idle'; // 'idle' | 'loading' | 'ok' | 'error' — read by HistoryScreen\n\n        /* ═══════════════════════════════════════════════════════════\n           UTILITY: Robust date normaliser — always returns YYYY-MM-DD\n        ═══════════════════════════════════════════════════════════ */\n        function toYMD(v) {\n            if (v === null || v === undefined || v === '') return '';\n            if (typeof v === 'number') {\n                const d = new Date(Math.round((v - 25569) * 86400 * 1000));\n                return d.getUTCFullYear() + '-' +\n                       String(d.getUTCMonth() + 1).padStart(2, '0') + '-' +\n                       String(d.getUTCDate()).padStart(2, '0');\n            }\n            const s = String(v).trim();\n            if (!s || s === 'undefined' || s === 'null') return '';\n            if (/^\\d{4}-\\d{2}-\\d{2}$/.test(s)) return s;\n            if (/^\\d{4}-\\d{2}-\\d{2}T/.test(s)) return s.substring(0, 10);\n            if (/^\\d{1,2}[-\\/]\\d{1,2}[-\\/]\\d{4}$/.test(s)) {\n                const p = s.split(/[-\\/]/);\n                return `${p[2]}-${p[1].padStart(2,'0')}-${p[0].padStart(2,'0')}`;\n            }\n            try {\n                const dt = new Date(s);\n                if (!isNaN(dt.getTime())) {\n                    return dt.getFullYear() + '-' +\n                           String(dt.getMonth() + 1).padStart(2, '0') + '-' +\n                           String(dt.getDate()).padStart(2, '0');\n                }\n            } catch (e) {}\n            return s;\n        }\n\n        function formatDate(s) {\n            const y = toYMD(s);\n            if (!y || y.length < 10) return s || '';\n            const [yr, mo, da] = y.split('-');\n            return `${da}-${mo}-${yr}`;\n        }\n\n        function sameDate(stored, filter) {\n            return toYMD(stored) === String(filter || '').trim();\n        }\n\n        function esc(s) { return String(s || '').replace(/\"/g, '&quot;').replace(/'/g, '&#39;'); }\n\n        // escHtml(): text-node-safe HTML escaping. esc() above stays untouched —\n        // its call sites are all value=\"...\"/onclick-string-arg contexts.\n        function escHtml(s) {\n            return String(s == null ? '' : s)\n                .replace(/&/g, '&amp;')\n                .replace(/</g, '&lt;')\n                .replace(/>/g, '&gt;')\n                .replace(/\"/g, '&quot;')\n                .replace(/'/g, '&#39;');\n        }\n\n        function toNum(v) { return Number(v) || 0; }\n\n        function sumWorkers(skilled, unskilled) { return toNum(skilled) + toNum(unskilled); }\n\n        /* ═══════════════════════════════════════════════════════════\n           DISPLAY HELPERS\n        ═══════════════════════════════════════════════════════════ */\n        function toTitleCase(str) {\n            if (!str) return '';\n            str = String(str).replace(/_/g, ' ').replace(/\\s+/g, ' ').trim();\n            let val = str.toLowerCase().replace(/\\b\\w/g, c => c.toUpperCase());\n            val = val.replace(/\\bRcc\\b/g, 'RCC')\n                     .replace(/\\bHvac\\b/g, 'HVAC')\n                     .replace(/\\bCctv\\b/g, 'CCTV')\n                     .replace(/\\bAc\\b/g, 'AC')\n                     .replace(/\\bDpr\\b/g, 'DPR');\n            return val;\n        }\n\n        /* ═══════════════════════════════════════════════════════════\n           API HELPERS\n        ═══════════════════════════════════════════════════════════ */\n        // The session lives in an HttpOnly cookie set by /api/proxy on login\n        // (lib/session.js) — same-origin fetches send it automatically. A 401\n        // means it expired or was revoked: drop back to the login screen.\n        function checkAuth(r) {\n            if (r.status === 401) handleAuthExpired();\n            return r.json();\n        }\n        const apiFetch = (action) => fetch(`${SHEET_URL}?action=${action}`).then(checkAuth);\n        const apiPost  = (body)   => fetch(SHEET_URL, {\n            method: 'POST',\n            headers: { 'Content-Type': 'application/json' },\n            body: JSON.stringify(body)\n        }).then(checkAuth);\n        const apiGetBootstrap = (dataVersion) =>\n            fetch(`${SHEET_URL}?action=getBootstrapData&dataVersion=${encodeURIComponent(dataVersion || '')}`).then(checkAuth);\n\n        /* ═══════════════════════════════════════════════════════════\n           TOAST\n        ═══════════════════════════════════════════════════════════ */\n        function showToast(msg) {\n            const t = document.getElementById('toast');\n            if (!t) return;\n            t.classList.remove('with-action');\n            t.textContent = msg;\n            t.classList.add('show');\n            clearTimeout(t._tid);\n            t._tid = setTimeout(() => t.classList.remove('show'), 2800);\n        }\n\n        // Warning/error toast with a clickable action button (e.g. \"Edit\n        // existing DPR\" on a duplicate-save conflict). Stays up longer than a\n        // plain toast since it requires a decision, not just a glance.\n        function showActionToast(msg, actionLabel, onAction) {\n            const t = document.getElementById('toast');\n            if (!t) return;\n            clearTimeout(t._tid);\n            t.innerHTML = '';\n            const span = document.createElement('span');\n            span.textContent = msg;\n            const btn = document.createElement('button');\n            btn.type = 'button';\n            btn.className = 'toast-action-btn';\n            btn.textContent = actionLabel;\n            btn.onclick = () => { t.classList.remove('show', 'with-action'); onAction(); };\n            t.appendChild(span);\n            t.appendChild(btn);\n            t.classList.add('show', 'with-action');\n            t._tid = setTimeout(() => t.classList.remove('show', 'with-action'), 6000);\n        }\n\n        /* ═══════════════════════════════════════════════════════════\n           CLIENT DATA LAYER — stale-while-revalidate cache over IndexedDB\n           ═══════════════════════════════════════════════════════════\n           This app is plain DOM-injected script (see generate_final.ps1),\n           not React function components, so the `swr` package's hooks\n           don't apply here — this is the same stale-while-revalidate\n           pattern (instant paint from cache, silent background refresh,\n           broadcast to every interested view) built directly on\n           IndexedDB, which — unlike localStorage's ~5-10MB cap — has\n           enough headroom to hold the FULL DPR history and material log\n           across sessions, not just a 45-day window.\n\n           getSnapshot(key)      — synchronous read of whatever's already\n                                    in memory (undefined until hydrate()\n                                    or a revalidate()/set() resolves).\n           subscribe(key, cb)    — cb fires on every future update to\n                                    `key`; returns an unsubscribe fn. This\n                                    is what lets a view \"subscribe to\n                                    cached state\" instead of owning its\n                                    own fetch-then-render logic.\n           hydrate(key)          — loads `key` from IndexedDB into memory\n                                    (once per key per session) and\n                                    notifies subscribers if it found\n                                    anything — the mechanism that paints a\n                                    view from a PRIOR session's data\n                                    before any network round-trip.\n           set(key, value)       — updates memory + notifies subscribers\n                                    immediately, persists to IndexedDB in\n                                    the background (never awaited).\n           revalidate(key, fn)   — awaits fn() (the network fetch), then\n                                    set()s the result. On failure, leaves\n                                    whatever's cached in place — a stale\n                                    view beats a broken one — and rethrows\n                                    so the caller can show a one-time\n                                    error only if nothing was ever cached.\n        ═══════════════════════════════════════════════════════════ */\n        const DataStore = (function () {\n            const DB_NAME  = 'dpr_cache_db';\n            const STORE    = 'kv';\n            const memory   = new Map();   // key -> value (synchronous snapshot)\n            const subs     = new Map();   // key -> Set<callback>\n            const hydrated = new Set();   // keys already loaded from IndexedDB this session\n            let dbPromise  = null;\n\n            function openDb() {\n                if (dbPromise) return dbPromise;\n                dbPromise = new Promise((resolve) => {\n                    if (!('indexedDB' in window)) { resolve(null); return; }\n                    try {\n                        const req = indexedDB.open(DB_NAME, 1);\n                        req.onupgradeneeded = () => { try { req.result.createObjectStore(STORE); } catch (e) {} };\n                        req.onsuccess = () => resolve(req.result);\n                        req.onerror   = () => resolve(null); // degrade to memory-only — never throws\n                    } catch (e) { resolve(null); }\n                });\n                return dbPromise;\n            }\n\n            async function dbGet(key) {\n                const db = await openDb();\n                if (!db) return undefined;\n                return new Promise((resolve) => {\n                    try {\n                        const rq = db.transaction(STORE, 'readonly').objectStore(STORE).get(key);\n                        rq.onsuccess = () => resolve(rq.result);\n                        rq.onerror   = () => resolve(undefined);\n                    } catch (e) { resolve(undefined); }\n                });\n            }\n\n            async function dbPut(key, value) {\n                const db = await openDb();\n                if (!db) return;\n                return new Promise((resolve) => {\n                    try {\n                        const tx = db.transaction(STORE, 'readwrite');\n                        tx.objectStore(STORE).put(value, key);\n                        tx.oncomplete = () => resolve();\n                        tx.onerror    = () => resolve(); // best-effort — a failed persist never breaks the caller\n                    } catch (e) { resolve(); }\n                });\n            }\n\n            function notify(key, value) {\n                (subs.get(key) || new Set()).forEach((cb) => {\n                    try { cb(value); } catch (e) { /* one bad subscriber shouldn't break the rest */ }\n                });\n            }\n\n            function getSnapshot(key) {\n                return memory.get(key);\n            }\n\n            function subscribe(key, callback) {\n                if (!subs.has(key)) subs.set(key, new Set());\n                subs.get(key).add(callback);\n                return () => { const s = subs.get(key); if (s) s.delete(callback); };\n            }\n\n            function set(key, value) {\n                memory.set(key, value);\n                notify(key, value);\n                return dbPut(key, value);\n            }\n\n            async function hydrate(key) {\n                if (hydrated.has(key)) return memory.get(key);\n                hydrated.add(key);\n                const cached = await dbGet(key);\n                if (cached !== undefined) {\n                    memory.set(key, cached);\n                    notify(key, cached);\n                }\n                return cached;\n            }\n\n            async function revalidate(key, fetcher) {\n                const value = await fetcher();\n                set(key, value);\n                return value;\n            }\n\n            return { getSnapshot, subscribe, hydrate, set, revalidate };\n        })();\n\n        // ── View subscriptions ──────────────────────────────────────\n        // Each of these is the SINGLE place that reacts to its key's data\n        // changing, whether that change came from an IndexedDB hydrate()\n        // at boot or a live revalidate() afterwards — every caller that\n        // used to fetch-then-render inline now just triggers a\n        // revalidate() and lets the subscriber do the rendering, so two\n        // different call sites can never render the same data two\n        // different ways.\n        DataStore.subscribe('dprHistory', (value) => {\n            _history = Array.isArray(value) ? value : [];\n            renderAdminAnalytics();\n            window.dispatchEvent(new CustomEvent('dpr:historyUpdated'));\n        });\n\n        DataStore.subscribe('materialLogs', (value) => {\n            _materialLogs = Array.isArray(value) ? value : [];\n            window.dispatchEvent(new CustomEvent('dpr:materialLogsUpdated'));\n        });\n\n        DataStore.subscribe('bootstrap', (data) => {\n            if (!data) return;\n            _users      = [SUPER_ADMIN, ...(Array.isArray(data.users) ? data.users : [])];\n            _projects   = Array.isArray(data.projects)   ? data.projects   : _projects;\n            _activities = Array.isArray(data.activities) ? data.activities : _activities;\n            _materials  = Array.isArray(data.materials)  ? data.materials  : _materials;\n            populateSiteDropdown();\n            renderLoginChips();\n            window.dispatchEvent(new CustomEvent('dpr:masterDataUpdated'));\n        });\n\n        // Merges _projects/_activities/_materials into the cached bootstrap\n        // snapshot without a network round-trip — called by the admin\n        // Projects/Activities/Materials panels after their own\n        // full-refresh fetch, so the cache stays warm without clobbering\n        // the dataVersion/users fields it doesn't have fresh values for.\n        // (Kept under its old name to avoid touching every admin-panel\n        // call site — it's fire-and-forget there, same as before.)\n        function saveMasterCacheToStorage() {\n            const prev = DataStore.getSnapshot('bootstrap') || {};\n            return DataStore.set('bootstrap', {\n                dataVersion: prev.dataVersion || '',\n                users:       prev.users || [],\n                projects:    _projects,\n                activities:  _activities,\n                materials:   _materials\n            });\n        }\n\n        /* ═══════════════════════════════════════════════════════════\n           BOOT — single consolidated bootstrap fetch after login\n        ═══════════════════════════════════════════════════════════ */\n        async function bootApp() {\n            const apList = document.getElementById('adminProjectList');\n            if (apList) apList.innerHTML = getSkeletonLoader();\n            const aaList = document.getElementById('adminActivityList');\n            if (aaList) aaList.innerHTML = getSkeletonLoader();\n\n            // Hydrate every key from IndexedDB in parallel. Each one that\n            // finds cached data fires the subscribers registered above\n            // immediately — painting the site dropdown, admin lists, and\n            // History/Materials tabs from the LAST successful fetch of\n            // any prior session, with no network round-trip on the\n            // critical path and no skeleton loader if there's anything\n            // at all to show.\n            await Promise.all([\n                DataStore.hydrate('bootstrap'),\n                DataStore.hydrate('dprHistory'),\n                DataStore.hydrate('materialLogs')\n            ]);\n            const cachedBootstrap = DataStore.getSnapshot('bootstrap');\n            if (!cachedBootstrap) showToast('⏳ Loading data...');\n\n            sendEntryCommand({ type: 'init' }); // form restores the saved draft, if any\n            loadHistory(); // full, unwindowed DPR history — the authoritative source; never overwritten by the bootstrap response below\n            loadMaterialLogs(); // consumption entries — the Executive Report annex needs them in Entry and History too\n\n            // Single consolidated round-trip — replaces four separate\n            // getUsers/getProjects/getActivities/getMaterials calls. Sends\n            // the cached dataVersion so the server can short-circuit with\n            // { unchanged: true } (no full sheet reads) when nothing has\n            // changed since the last boot.\n            try {\n                const res = await apiGetBootstrap(cachedBootstrap ? cachedBootstrap.dataVersion : '');\n                if (res && !res.unchanged) {\n                    await DataStore.revalidate('bootstrap', () => res);\n                    // A first-ever visit (nothing hydrated from IndexedDB\n                    // yet) gets the Materials tab's 45-day window as a\n                    // head start. Once a real materialLogs snapshot\n                    // exists, this never overwrites it — loadMaterialLogs()\n                    // (tab-open, or already in flight) is the authority.\n                    if (Array.isArray(res.recentMaterialLogs) && !DataStore.getSnapshot('materialLogs')) {\n                        DataStore.set('materialLogs', res.recentMaterialLogs);\n                    }\n                }\n            } catch (e) {\n                if (!cachedBootstrap) showToast('⚠️ Could not reach server');\n            }\n        }\n\n        /* ═══════════════════════════════════════════════════════════\n           LOGIN / LOGOUT\n        ═══════════════════════════════════════════════════════════ */\n        function renderLoginChips() {\n            const wrap = document.getElementById('userChips');\n            if (!wrap) return;\n            wrap.innerHTML = '';\n            _users.forEach(u => {\n                const c = document.createElement('div');\n                c.className   = 'user-chip';\n                c.textContent = u.username;\n                c.onclick     = () => {\n                    document.getElementById('loginName').value = u.username;\n                    document.getElementById('loginPass').focus();\n                };\n                wrap.appendChild(c);\n            });\n        }\n\n        async function doLogin() {\n            const rawUname = document.getElementById('loginName').value;\n            const rawPass  = document.getElementById('loginPass').value;\n            \n            // Explicit sanitisation of credentials before transmitting\n            const uname = (rawUname || '').trim().toLowerCase();\n            const pass  = (rawPass || '').trim();\n            \n            const err   = document.getElementById('loginErr');\n            if (!uname || !pass) { err.textContent = '❌ Enter username and password.'; return; }\n            err.style.color = 'var(--primary)';\n            err.textContent = '⏳ Authenticating...';\n            try {\n                const res = await apiPost({ action: 'login', username: uname, password: pass });\n                if (res && res.error) {\n                    err.style.color = '#e53e3e';\n                    err.textContent = '❌ Server Error: ' + res.error;\n                    return;\n                }\n                if (res && res.success && res.user) {\n                    _currentUser = res.user;\n                } else {\n                    err.style.color = '#e53e3e';\n                    err.textContent = '❌ Invalid username or password.';\n                    return;\n                }\n            } catch (e) {\n                err.style.color = '#e53e3e';\n                err.textContent = '⚠️ Connection error. Try again.';\n                return;\n            }\n            err.textContent = '';\n            showApp();\n        }\n\n        function updateThemeToggleIcon() {\n            const btn = document.getElementById('themeToggleBtn');\n            if (!btn) return;\n            const theme = document.documentElement.getAttribute('data-theme') || 'light';\n            btn.innerHTML = theme === 'dark' ? '&#9728;&#65039;' : '&#127769;';\n        }\n\n        function toggleTheme() {\n            const current = document.documentElement.getAttribute('data-theme') || 'light';\n            const next = current === 'dark' ? 'light' : 'dark';\n            document.documentElement.setAttribute('data-theme', next);\n            try { localStorage.setItem('dprTheme', next); } catch (e) {}\n            updateThemeToggleIcon();\n            window.dispatchEvent(new CustomEvent('dpr:themeChanged', { detail: { theme: next } }));\n        }\n        window.toggleTheme = toggleTheme;\n\n        function showLoginScreen() {\n            _currentUser = null;\n            document.getElementById('loginOverlay').style.display = 'flex';\n            document.getElementById('loginPass').value = '';\n            renderLoginChips();\n        }\n\n        let _authExpiredShown = false;\n        function handleAuthExpired() {\n            if (!_currentUser || _authExpiredShown) return;\n            _authExpiredShown = true;\n            showLoginScreen();\n            const err = document.getElementById('loginErr');\n            if (err) { err.style.color = '#e53e3e'; err.textContent = '🔒 Your session expired — please sign in again.'; }\n            setTimeout(() => { _authExpiredShown = false; }, 3000);\n        }\n        window.__onAuthRequired = handleAuthExpired; // React components call this on a 401\n\n        async function restoreSession() {\n            try {\n                const res = await fetch(`${SHEET_URL}?action=session`).then(r => r.json());\n                if (res && res.user) { _currentUser = res.user; showApp(); }\n            } catch (e) { /* offline or server down — stay on the login screen */ }\n        }\n\n        function doLogout() {\n            fetch(SHEET_URL, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ action: 'logout' }) }).catch(() => {});\n            _currentUser = null;\n            document.getElementById('loginOverlay').style.display = 'flex';\n            document.getElementById('loginPass').value = '';\n            document.getElementById('loginErr').textContent = '';\n            renderLoginChips();\n        }\n\n        function showApp() {\n            document.getElementById('loginOverlay').style.display = 'none';\n            document.getElementById('headerUser').textContent =\n                '👤 ' + _currentUser.username + (_currentUser.role === 'admin' ? ' · Admin' : '');\n            document.getElementById('adminTabBtn').style.display =\n                _currentUser.role === 'admin' ? 'block' : 'none';\n            bootApp();\n        }\n\n        /* ═══════════════════════════════════════════════════════════\n           TABS\n        ═══════════════════════════════════════════════════════════ */\n        function switchTab(tab, btn) {\n            closeDPRModal();\n            document.querySelectorAll('.tab-page').forEach(p => { p.classList.remove('active'); p.style.display = 'none'; });\n            document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));\n            const pg = document.getElementById('tab' + tab);\n            if (pg) { pg.classList.add('active'); pg.style.display = 'block'; }\n            const ab = btn || document.getElementById('tabBtn' + tab);\n            if (ab) ab.classList.add('active');\n            if (tab === 'Dashboard') window.dispatchEvent(new CustomEvent('dpr:historyUpdated'));\n            if (tab === 'Admin')     renderAdminPanel();\n            if (tab === 'Materials') loadMaterialLogs();\n        }\n\n        function resetAndSwitchToForm(btn, forceNew) {\n            closeDPRModal();\n            document.querySelectorAll('.tab-page').forEach(p => { p.classList.remove('active'); p.style.display = 'none'; });\n            document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));\n            const fp = document.getElementById('tabForm');\n            if (fp) { fp.classList.add('active'); fp.style.display = 'block'; }\n            (btn || document.getElementById('tabBtnForm')).classList.add('active');\n            sendEntryCommand({ type: forceNew ? 'reset' : 'init' });\n        }\n\n        /* ═══════════════════════════════════════════════════════════\n           DPR ENTRY FORM — now a real React component, see\n           /components/dpr/DprEntryForm.jsx, portal-mounted into\n           #__entry_mount__. It owns the form state, validation, draft\n           (localStorage 'dpr_form_draft') and saveDPR/editDPR/saveMaterialLog\n           submission. Interop bridge:\n             legacy → React: sendEntryCommand({ type: 'init' | 'reset' | 'edit', record })\n             React → legacy: window.__get*() accessors and the showToast/showActionToast/editDPR/\n                             loadHistory/loadMaterialLogs globals.\n           'dpr:masterDataUpdated' fires whenever projects/activities/\n           materials change. Commands sent before the component mounts are\n           queued and replayed on mount.\n        ═══════════════════════════════════════════════════════════ */\n        function sendEntryCommand(cmd) {\n            if (typeof window.__dprEntryHandler === 'function') { window.__dprEntryHandler(cmd); return; }\n            (window.__dprEntryQueue = window.__dprEntryQueue || []).push(cmd);\n        }\n\n        /* ═══════════════════════════════════════════════════════════\n           SITE DROPDOWN — with sub-project indentation\n        ═══════════════════════════════════════════════════════════ */\n        function getLocalTodayYMD() {\n            const d = new Date();\n            const y = d.getFullYear();\n            const m = String(d.getMonth() + 1).padStart(2, '0');\n            const day = String(d.getDate()).padStart(2, '0');\n            return `${y}-${m}-${day}`;\n        }\n\n        // Every site/project <select> is rendered by a React component now\n        // (Entry, History, Materials). Kept under its old name because the\n        // admin project handlers call it after changing _projects.\n        function populateSiteDropdown() {\n            window.dispatchEvent(new CustomEvent('dpr:masterDataUpdated'));\n        }\n\n        /* ═══════════════════════════════════════════════════════════\n           MATERIALS — now a real React component, see\n           /components/materials/MaterialsScreen.jsx, portal-mounted into\n           #__materials_mount__. It owns the consumption-entry form, the\n           Trust-only Total Material Summary, filters and the entries list,\n           and posts saveMaterialLog itself. Interop bridge:\n             React → legacy: window.__getMaterialLogs/__getMaterialLogsStatus/\n                             __getMaterials/__getProjects/__getCurrentUser,\n                             and loadMaterialLogs() below.\n             legacy → React: 'dpr:materialLogsUpdated' (data or load status\n                             changed) and 'dpr:masterDataUpdated'.\n        ═══════════════════════════════════════════════════════════ */\n        function loadMaterialLogs() {\n            // Instant paint: the 'materialLogs' subscriber already ran if\n            // IndexedDB or the bootstrap response had anything cached — the\n            // status only decides whether MaterialsScreen shows a loading/\n            // error state when there's nothing cached to show.\n            _materialLogsStatus = 'loading';\n            window.dispatchEvent(new CustomEvent('dpr:materialLogsUpdated'));\n            DataStore.revalidate('materialLogs', () => apiFetch('getMaterialLogs'))\n                .then(() => { _materialLogsStatus = 'ok'; })\n                .catch(() => { _materialLogsStatus = 'error'; })\n                .finally(() => window.dispatchEvent(new CustomEvent('dpr:materialLogsUpdated')));\n        }\n        window.loadMaterialLogs = loadMaterialLogs;\n\n        function syncOfflineQueue() {\n            const q = JSON.parse(localStorage.getItem('dprOfflineQ') || '[]');\n            if (!q.length) { showToast('✅ Nothing to sync'); return; }\n            showToast(`🔄 Syncing ${q.length} queued DPR(s)...`);\n            Promise.all(q.map(p => apiPost(p)))\n                .then(() => { localStorage.removeItem('dprOfflineQ'); showToast('✅ All synced!'); loadHistory(); })\n                .catch(() => showToast('⚠️ Sync failed'));\n        }\n\n        /* ═══════════════════════════════════════════════════════════\n           HISTORY  (no default date filter — shows ALL records)\n        ═══════════════════════════════════════════════════════════ */\n        function loadHistory() {\n            // Instant paint: the 'dprHistory' subscriber already ran if\n            // IndexedDB had a prior session's history cached — the status\n            // only decides whether HistoryScreen shows a skeleton/error\n            // when there's nothing cached to show.\n            _historyStatus = 'loading';\n            window.dispatchEvent(new CustomEvent('dpr:historyUpdated'));\n            DataStore.revalidate('dprHistory', () => apiFetch(''))\n                .then(() => { _historyStatus = 'ok'; })\n                .catch(() => { _historyStatus = 'error'; })\n                .finally(() => window.dispatchEvent(new CustomEvent('dpr:historyUpdated')));\n        }\n\n        /* ═══════════════════════════════════════════════════════════\n           OVERHAUL HELPER FUNCTIONS\n        ═══════════════════════════════════════════════════════════ */\n        function getSkeletonLoader() {\n            return `\n            <div class=\"skeleton-card\">\n                <div class=\"skeleton-block\" style=\"width: 40%; height: 18px;\"></div>\n                <div class=\"skeleton-block\" style=\"width: 75%; height: 14px;\"></div>\n                <div class=\"skeleton-block\" style=\"width: 25%; height: 26px; border-radius: 4px; margin-top: 6px;\"></div>\n            </div>\n            <div class=\"skeleton-card\">\n                <div class=\"skeleton-block\" style=\"width: 50%; height: 18px;\"></div>\n                <div class=\"skeleton-block\" style=\"width: 60%; height: 14px;\"></div>\n                <div class=\"skeleton-block\" style=\"width: 25%; height: 26px; border-radius: 4px; margin-top: 6px;\"></div>\n            </div>\n            <div class=\"skeleton-card\">\n                <div class=\"skeleton-block\" style=\"width: 35%; height: 18px;\"></div>\n                <div class=\"skeleton-block\" style=\"width: 80%; height: 14px;\"></div>\n                <div class=\"skeleton-block\" style=\"width: 25%; height: 26px; border-radius: 4px; margin-top: 6px;\"></div>\n            </div>\n            `;\n        }\n\n        // Flattens _history into one row per activity line item (plus a header row).\n        // Shared by both the CSV and Excel export paths so they never drift apart.\n        function buildMasterLogRows() {\n            const headers = [\n                'Date', 'Site', 'Supervisor (Created By)', 'Last Edited By', 'Submitted At',\n                'Total DPR Manpower', 'Activity Category (Main)', 'Sub-Activity',\n                'Skilled Workers', 'Unskilled Workers', 'Activity Total', 'Note'\n            ];\n            const rows = [headers];\n            _history.forEach(item => {\n                const dateStr = toYMD(item.date);\n                const siteStr = item.site || '';\n                const createdBy = item.by || '';\n                const editedBy = item.editedBy || '';\n                const submittedAt = item.submittedAt || '';\n                const totalManpower = item.total || 0;\n\n                // civilActivities/interiorActivities are only API storage\n                // buckets — pool them; `details` is the oldest fallback.\n                const pooled = [...(item.civilActivities || []), ...(item.interiorActivities || [])];\n                const activities = pooled.length ? pooled : (Array.isArray(item.details) ? item.details : []);\n\n                if (activities.length === 0) {\n                    rows.push([dateStr, siteStr, createdBy, editedBy, submittedAt, totalManpower, '', '', 0, 0, 0, '']);\n                } else {\n                    activities.forEach(act => {\n                        const mainAct = act.main_activity || act.activity || '';\n                        // Saved rows carry the sub-activity name in `activity` when one was chosen.\n                        const subAct = act.sub_activity || (act.main_activity && act.activity && act.activity !== act.main_activity ? act.activity : '');\n                        const sk = Number(act.skilled) || 0;\n                        const un = Number(act.unskilled) || 0;\n                        const actTotal = sk + un;\n                        const noteStr = act.note || '';\n                        rows.push([dateStr, siteStr, createdBy, editedBy, submittedAt, totalManpower, mainAct, subAct, sk, un, actTotal, noteStr]);\n                    });\n                }\n            });\n            return rows;\n        }\n\n        // All-time per-site rollup, used as the \"Site Summary\" sheet in the Excel export.\n        function buildSiteSummaryRows() {\n            const siteMap = {};\n            _history.forEach(item => {\n                const site = item.site || 'Unknown';\n                if (!siteMap[site]) siteMap[site] = { totalWorkers: 0, totalDPRs: 0 };\n                siteMap[site].totalWorkers += Number(item.total) || 0;\n                siteMap[site].totalDPRs += 1;\n            });\n            const rows = [['Site', 'Total Workers (All Time)', 'Total DPRs', 'Avg Workers / DPR']];\n            Object.entries(siteMap)\n                .sort((a, b) => b[1].totalWorkers - a[1].totalWorkers)\n                .forEach(([site, d]) => {\n                    rows.push([site, d.totalWorkers, d.totalDPRs, d.totalDPRs ? Math.round(d.totalWorkers / d.totalDPRs) : 0]);\n                });\n            return rows;\n        }\n\n        function exportMasterLogCSV() {\n            if (!_history.length) { showToast('⚠️ No history records to export'); return; }\n            const rows = buildMasterLogRows();\n            const csvContent = \"data:text/csv;charset=utf-8,\" + rows.map(e => e.map(val => {\n                let s = String(val === null || val === undefined ? '' : val).replace(/\"/g, '\"\"');\n                if (s.includes(',') || s.includes('\"') || s.includes('\\n') || s.includes('\\r')) {\n                    s = `\"${s}\"`;\n                }\n                return s;\n            }).join(\",\")).join(\"\\n\");\n            const encodedUri = encodeURI(csvContent);\n            const link = document.createElement(\"a\");\n            link.setAttribute(\"href\", encodedUri);\n            link.setAttribute(\"download\", `TPD_DPR_Master_Log_${getLocalTodayYMD()}.csv`);\n            document.body.appendChild(link);\n            link.click();\n            document.body.removeChild(link);\n            showToast('✅ CSV Exported!');\n        }\n\n        function exportMasterLogExcel() {\n            if (!_history.length) { showToast('⚠️ No history records to export'); return; }\n            if (typeof XLSX === 'undefined') { showToast('⚠️ Excel library still loading — try again in a moment'); return; }\n            const wb = XLSX.utils.book_new();\n            XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(buildMasterLogRows()), 'Master Log');\n            XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(buildSiteSummaryRows()), 'Site Summary');\n            XLSX.writeFile(wb, `TPD_DPR_Master_Log_${getLocalTodayYMD()}.xlsx`);\n            showToast('✅ Excel Exported!');\n        }\n        window.exportMasterLogExcel = exportMasterLogExcel;\n\n        // True vector PDF (selectable text, paginated with repeated headers)\n        // for the Master Log. Per-record DPR PDFs are built separately, in\n        // lib/report/exportReport.js.\n        function exportMasterLogPDF() {\n            if (!_history.length) { showToast('⚠️ No history records to export'); return; }\n            if (typeof window.jspdf === 'undefined') { showToast('⚠️ PDF library still loading — try again in a moment'); return; }\n            const { jsPDF } = window.jspdf;\n            const doc = new jsPDF({ orientation: 'landscape', unit: 'pt', format: 'a4' });\n            if (typeof doc.autoTable !== 'function') { showToast('⚠️ PDF table library still loading — try again in a moment'); return; }\n\n            const rows = buildMasterLogRows();\n            const headerRow = rows[0];\n            const bodyRows = rows.slice(1);\n\n            doc.setFontSize(14);\n            doc.text('Trimandir Construction Project — DPR Master Log', 40, 30);\n            doc.autoTable({\n                head: [headerRow],\n                body: bodyRows,\n                startY: 45,\n                styles: { fontSize: 7, cellPadding: 3 },\n                headStyles: { fillColor: [49, 46, 129] },\n                margin: { top: 45 },\n                didDrawPage: (data) => {\n                    doc.setFontSize(8);\n                    doc.text(`Page ${doc.internal.getNumberOfPages()}`, data.settings.margin.left, doc.internal.pageSize.getHeight() - 10);\n                }\n            });\n            doc.save(`TPD_DPR_Master_Log_${getLocalTodayYMD()}.pdf`);\n            showToast('✅ PDF Exported!');\n        }\n        window.exportMasterLogPDF = exportMasterLogPDF;\n\n        function renderAdminAnalytics() {\n            const todayYMD = getLocalTodayYMD();\n            const todayDPRs = _history.filter(h => toYMD(h.date) === todayYMD);\n            const workforceToday = todayDPRs.reduce((sum, h) => sum + (Number(h.total) || 0), 0);\n            \n            const siteCounts = {};\n            _history.forEach(h => { if (h.site) siteCounts[h.site] = (siteCounts[h.site] || 0) + 1; });\n            let mostActiveSite = '—';\n            let maxCount = 0;\n            Object.entries(siteCounts).forEach(([site, count]) => {\n                if (count > maxCount) { maxCount = count; mostActiveSite = site; }\n            });\n            const displayActiveSite = mostActiveSite.length > 15 ? mostActiveSite.substring(0, 15) + '...' : mostActiveSite;\n            \n            const activeCount = _projects.filter(p => p.status === 'active').length;\n            const totalCount = _projects.length;\n            \n            const tfEl = document.getElementById('adminWorkforceToday');\n            if (tfEl) tfEl.textContent = workforceToday;\n            const masEl = document.getElementById('adminActiveSite');\n            if (masEl) {\n                masEl.textContent = displayActiveSite;\n                masEl.title = mostActiveSite;\n            }\n            const prEl = document.getElementById('adminProjectRatio');\n            if (prEl) prEl.textContent = `${activeCount}/${totalCount}`;\n        }\n\n        /* ═══════════════════════════════════════════════════════════\n           HISTORY — now a real React component, see\n           /components/history/HistoryScreen.jsx, portal-mounted into\n           #__history_mount__. It owns filters, sorting, pagination, the\n           per-record ⋮ menu and the View modal. Interop bridge:\n             React → legacy: window.__getHistory/__getHistoryStatus/\n                             __getProjects/__getUsers/__getCurrentUser, and\n                             the index-based editDPR/requestEditDPR/deleteDPR\n                             globals below. Report JPG/PDF/WhatsApp/Share\n                             live in lib/report/ (ExecutiveReport).\n             legacy → React: 'dpr:historyUpdated' (data or load status\n                             changed), 'dpr:masterDataUpdated', and\n                             'dpr:closeDprModal' (via closeDPRModal()).\n        ═══════════════════════════════════════════════════════════ */\n        function closeDPRModal() {\n            window.dispatchEvent(new CustomEvent('dpr:closeDprModal'));\n        }\n\n        function deleteDPR(i) {\n            if (!_currentUser || _currentUser.role !== 'admin') { showToast('❌ Only Admin can delete'); return; }\n            if (!confirm('Delete this DPR record permanently?')) return;\n            const item = _history[i];\n            const key  = toYMD(item.date) + '||' + String(item.site).trim();\n            apiPost({ action: 'delete', id: key })\n                .then(res => {\n                    if (res && res.error) { showToast('⚠️ Delete failed: ' + res.error); return; }\n                    showToast('🗑️ Deleted!'); loadHistory();\n                })\n                .catch(() => showToast('⚠️ Delete failed'));\n        }\n\n        /* ═══════════════════════════════════════════════════════════\n           EDIT DPR — permission gate; DprEntryForm rebuilds the rows\n        ═══════════════════════════════════════════════════════════ */\n        function editDPR(i) {\n            const item = _history[i];\n            if (!item || !_currentUser) return;\n            const isAdmin  = _currentUser.role === 'admin';\n            const isOwn    = item.by === _currentUser.username;\n            const sub      = Number(item.submittedAt) || (item.submittedAt ? new Date(item.submittedAt).getTime() : 0);\n            const within15 = sub && (Date.now() - sub) < 15 * 60 * 1000;\n            const granted  = item.editPermission === 'granted';\n            if (!isAdmin && !isOwn)               { showToast('❌ You can only edit your own DPRs'); return; }\n            if (!isAdmin && !within15 && !granted) { showToast('🔒 Edit window expired. Request Edit first.'); return; }\n\n            sendEntryCommand({ type: 'edit', record: item });\n\n            closeDPRModal();\n            switchTab('Form', document.getElementById('tabBtnForm'));\n            showToast('✏️ Loaded for editing — click Update DPR when done');\n        }\n\n        async function requestEditDPR(i) {\n            const item = _history[i];\n            if (!item || !_currentUser) return;\n            if (!confirm('Request edit permission from Admin for this DPR?')) return;\n            showToast('📤 Sending request...');\n            try {\n                const res = await apiPost({ action: 'requestEditDPR', key: toYMD(item.date) + '||' + String(item.site).trim(), requestedBy: _currentUser.username });\n                if (res && res.error) { showToast('⚠️ Request failed: ' + res.error); return; }\n                showToast('✅ Request sent!');\n                loadHistory();\n            } catch (e) { showToast('⚠️ Request failed'); }\n        }\n\n        async function approveEditDPR(key) {\n            if (!confirm('Approve edit access for this DPR?')) return;\n            showToast('⏳ Approving...');\n            try {\n                const res = await apiPost({ action: 'approveEditDPR', key });\n                if (res && res.error) { showToast('⚠️ Approval failed: ' + res.error); return; }\n                showToast('✅ Edit access granted!');\n                loadHistory();\n            } catch (e) { showToast('⚠️ Approval failed'); }\n        }\n\n        function renderPendingEditRequests() {\n            const el      = document.getElementById('pendingEditRequests');\n            if (!el) return;\n            const pending = _history.filter(item => item.editPermission === 'pending');\n            if (!pending.length) {\n                el.innerHTML = '<p style=\"color:var(--muted);font-size:13px;text-align:center;padding:10px;\">✅ No pending requests.</p>';\n                return;\n            }\n            el.innerHTML = pending.map(item => {\n                const key = toYMD(item.date) + '||' + String(item.site).trim();\n                return `<div class=\"admin-user-row\">\n                    <div>\n                        <div class=\"admin-user-info\">📅 ${formatDate(toYMD(item.date))} &nbsp;·&nbsp; 📍 ${item.site || '—'}</div>\n                        <div class=\"admin-user-sub\">Requested by: <b>${item.requestedBy || '—'}</b></div>\n                    </div>\n                    <button class=\"btn-green btn-sm\" style=\"width:auto;padding:6px 14px;\" onclick=\"approveEditDPR('${key}')\">✅ Approve</button>\n                </div>`;\n            }).join('');\n        }\n\n        /* ═══════════════════════════════════════════════════════════\n           ADMIN PANEL\n        ═══════════════════════════════════════════════════════════ */\n        function renderAdminPanel() {\n            renderAdminAnalytics();\n            renderPendingEditRequests();\n            renderAdminUsers();\n            renderAdminProjects();\n            renderAdminActivities();\n            renderAdminMaterials();\n        }\n\n        // ── Users ───────────────────────────────────────────────────\n        async function createUser() {\n            const username    = document.getElementById('newUsername').value.trim();\n            const displayName = document.getElementById('newDisplayName').value.trim();\n            const password    = document.getElementById('newPassword').value.trim();\n            const role        = document.getElementById('newRole').value;\n            if (!username || !password) { showToast('⚠️ Username and password required'); return; }\n            if (_users.find(u => u.username.toLowerCase() === username.toLowerCase())) { showToast('⚠️ Username already exists'); return; }\n            showToast('⏳ Creating user...');\n            try {\n                const res = await apiPost({ action: 'createUser', username, displayName: displayName || username, password, role });\n                if (res && res.error) { showToast('❌ ' + res.error); return; }\n                // Refresh user list from server to pick up the new row\n                const d = await apiFetch('getUsers').catch(() => []);\n                if (Array.isArray(d)) _users = [SUPER_ADMIN, ...d];\n                renderLoginChips(); renderAdminUsers();\n                ['newUsername','newDisplayName','newPassword'].forEach(id => { const el = document.getElementById(id); if (el) el.value = ''; });\n                showToast('✅ User created successfully!');\n            } catch (e) {\n                showToast('❌ Network error: ' + e.message);\n            }\n        }\n\n        async function deleteUser(username) {\n            if (username === SUPER_ADMIN.username) return;\n            if (!confirm(`Delete user \"${username}\"?`)) return;\n            await apiPost({ action: 'deleteUser', username });\n            const d = await apiFetch('getUsers').catch(() => []);\n            if (Array.isArray(d)) _users = [SUPER_ADMIN, ...d];\n            renderLoginChips(); renderAdminUsers();\n            showToast('✅ User deleted!');\n        }\n\n        async function resetPassword(username) {\n            const p = prompt(`New password for \"${username}\":`);\n            if (!p || !p.trim()) return;\n            await apiPost({ action: 'resetPassword', username, password: p.trim() });\n            showToast('✅ Password updated!');\n        }\n\n        function renderAdminUsers() {\n            const el = document.getElementById('adminUserList');\n            if (!el) return;\n            el.innerHTML = _users.map(u => {\n                const sup = u.username === SUPER_ADMIN.username;\n                const userDPRs = _history.filter(h => String(h.by).trim().toLowerCase() === u.username.trim().toLowerCase());\n                const totalSubmitted = userDPRs.length;\n                let lastSubDate = 'Never';\n                let isInactive = false;\n                \n                if (totalSubmitted > 0) {\n                    const times = userDPRs.map(h => {\n                        const ymd = toYMD(h.date);\n                        return ymd ? new Date(ymd).getTime() : 0;\n                    }).filter(Boolean);\n                    if (times.length) {\n                        const maxTime = Math.max(...times);\n                        const maxDate = new Date(maxTime);\n                        const y = maxDate.getFullYear();\n                        const m = String(maxDate.getMonth() + 1).padStart(2, '0');\n                        const d = String(maxDate.getDate()).padStart(2, '0');\n                        lastSubDate = `${d}-${m}-${y}`;\n                        \n                        const diffTime = Date.now() - maxTime;\n                        const diffDays = diffTime / (1000 * 60 * 60 * 24);\n                        if (diffDays >= 3) {\n                            isInactive = true;\n                        }\n                    } else {\n                        isInactive = true;\n                    }\n                } else {\n                    isInactive = true;\n                }\n                \n                const statusBadge = isInactive \n                    ? `<span style=\"background:#fee2e2;color:#ef4444;padding:2px 6px;border-radius:4px;font-size:10px;font-weight:700;margin-left:6px;display:inline-block;\">⚠️ Inactive</span>`\n                    : `<span style=\"background:#dcfce7;color:#10b981;padding:2px 6px;border-radius:4px;font-size:10px;font-weight:700;margin-left:6px;display:inline-block;\">🟢 Active</span>`;\n\n                return `<div class=\"admin-user-row\" style=\"flex-direction:column;align-items:stretch;gap:4px;padding:12px;\">\n                    <div style=\"display:flex;justify-content:space-between;align-items:center;\">\n                        <div>\n                            <span class=\"admin-user-info\" style=\"font-size:14px;\">👤 ${escHtml(u.username)}</span>\n                            ${statusBadge}\n                        </div>\n                        <div style=\"display:flex;gap:6px;\">\n                            ${!sup ? `<button class=\"btn-gray btn-sm\" style=\"width:auto;padding:4px 8px;margin:0;\" onclick=\"resetPassword('${u.username}')\" title=\"Reset Password\">🔑</button>` : ''}\n                            ${!sup ? `<button class=\"btn-red btn-sm\"  style=\"width:auto;padding:4px 8px;margin:0;\" onclick=\"deleteUser('${u.username}')\" title=\"Delete User\">🗑️</button>`\n                                   : `<span style=\"font-size:11px;color:var(--muted);\">Protected</span>`}\n                        </div>\n                    </div>\n                    <div class=\"admin-user-sub\" style=\"margin-top:4px;font-size:12px;display:grid;grid-template-columns:1fr 1fr;gap:4px;border-top:1px solid #f1f5f9;padding-top:6px;\">\n                        <div>Display: <b>${u.displayName ? escHtml(toTitleCase(u.displayName)) : escHtml(u.username)}</b></div>\n                        <div>Role: <b>${u.role === 'admin' ? 'Admin' : 'Supervisor'}</b></div>\n                        <div>Total DPRs: <b>${totalSubmitted}</b></div>\n                        <div>Last Upload: <b>${lastSubDate}</b></div>\n                    </div>\n                </div>`;\n            }).join('');\n        }\n\n        // ── Projects ────────────────────────────────────────────────\n        async function adminAddProject() {\n            const name     = document.getElementById('newProjectName').value.trim();\n            const parentId = document.getElementById('newProjectParent').value;\n            if (!name) { showToast('⚠️ Enter a project name'); return; }\n            showToast('⏳ Adding...');\n            await apiPost({ action: 'addProject', project_name: name, parent_id: parentId || '' });\n            const d = await apiFetch('getProjects').catch(() => _projects);\n            if (Array.isArray(d)) _projects = d;\n            populateSiteDropdown(); renderAdminProjects();\n            document.getElementById('newProjectName').value = '';\n            showToast('✅ Project added!');\n        }\n\n        async function toggleProject(id, curStatus) {\n            const ns = curStatus === 'active' ? 'inactive' : 'active';\n            await apiPost({ action: 'updateProject', id, status: ns });\n            const d = await apiFetch('getProjects').catch(() => _projects);\n            if (Array.isArray(d)) _projects = d;\n            populateSiteDropdown(); renderAdminProjects();\n            showToast(`✅ ${ns === 'active' ? 'Activated' : 'Deactivated'}!`);\n        }\n\n        async function editProjectName(id, cur) {\n            const n = prompt('Edit project name:', cur);\n            if (!n || n.trim() === cur) return;\n            await apiPost({ action: 'updateProject', id, project_name: n.trim() });\n            const d = await apiFetch('getProjects').catch(() => _projects);\n            if (Array.isArray(d)) _projects = d;\n            populateSiteDropdown(); renderAdminProjects();\n            showToast('✅ Project renamed!');\n        }\n\n        async function deleteProject(id, name) {\n            if (!confirm(`Are you sure you want to delete \"${name}\"?\\nThis will permanently delete this project and all its sub-projects from the Google Sheet.`)) return;\n            showToast('⏳ Deleting...');\n            try {\n                const res = await apiPost({ action: 'deleteProject', id });\n                if (res.error) {\n                    showToast('⚠️ Error: ' + res.error);\n                } else {\n                    showToast(`✅ Deleted project and child dependencies!`);\n                    const d = await apiFetch('getProjects').catch(() => _projects);\n                    if (Array.isArray(d)) _projects = d;\n                    populateSiteDropdown();\n                    renderAdminProjects();\n                }\n            } catch (e) {\n                showToast('⚠️ Delete failed');\n            }\n        }\n\n        function renderAdminProjects() {\n            saveMasterCacheToStorage();\n            const el      = document.getElementById('adminProjectList');\n            if (!el) return;\n            const tops    = _projects.filter(p => (!p.parent_id || String(p.parent_id).trim() === ''));\n            const parentSel = document.getElementById('newProjectParent');\n            if (parentSel) {\n                parentSel.innerHTML = '<option value=\"\">— None (Top-level) —</option>' +\n                    tops.filter(p => p.status === 'active')\n                        .map(p => `<option value=\"${p.id}\">${escHtml(p.project_name)}</option>`).join('');\n            }\n            if (!_projects.length) { el.innerHTML = '<p style=\"color:var(--muted);font-size:13px;text-align:center;padding:12px;\">No projects yet.</p>'; return; }\n            el.innerHTML = tops.map(proj => {\n                const subs = _projects.filter(p => String(p.parent_id).trim() === String(proj.id).trim());\n                const act  = proj.status === 'active';\n                return `\n                <div draggable=\"true\" data-id=\"${proj.id}\" ondragstart=\"dragStart(event)\" ondragover=\"dragOver(event)\" ondrop=\"dropProject(event)\" style=\"margin-bottom:12px;border:1.5px solid var(--border);border-radius:8px;overflow:hidden;cursor:move;\">\n                    <div style=\"background:#f8fafc;padding:10px 14px;display:flex;align-items:center;justify-content:space-between;gap:8px;\">\n                        <div>\n                            <span style=\"font-weight:700;font-size:14px;color:var(--primary);\">📍 ${escHtml(proj.project_name)}</span>\n                            <span style=\"font-size:11px;margin-left:8px;color:${act ? '#38a169' : '#e53e3e'};\">${act ? '🟢' : '🔴'}</span>\n                        </div>\n                        <div style=\"display:flex;gap:6px;\">\n                            <button class=\"btn-blue btn-sm\" style=\"width:auto;padding:4px 8px;font-size:11px;\"\n                                    onclick=\"editProjectName('${proj.id}','${esc(proj.project_name)}')\">✏️</button>\n                            <button class=\"btn-red btn-sm\" style=\"width:auto;padding:4px 8px;font-size:11px;background:#e53e3e;border-color:#e53e3e;\"\n                                    onclick=\"deleteProject('${proj.id}','${esc(proj.project_name)}')\">🗑️</button>\n                            <button class=\"${act ? 'btn-red' : 'btn-green'} btn-sm\"\n                                    style=\"width:auto;padding:4px 10px;font-size:11px;\"\n                                    onclick=\"toggleProject('${proj.id}','${proj.status}')\">\n                                ${act ? '🔴 Off' : '🟢 On'}\n                            </button>\n                        </div>\n                    </div>\n                    <div style=\"padding:6px 14px 8px;\">\n                        ${subs.length\n                            ? subs.map(s => `\n                            <div style=\"display:flex;justify-content:space-between;align-items:center;padding:5px 0;border-bottom:1px solid #f1f5f9;\">\n                                <span style=\"font-size:13px;${s.status !== 'active' ? 'color:var(--muted);text-decoration:line-through;' : ''}\">↳ ${escHtml(s.project_name)}</span>\n                                <div style=\"display:flex;gap:5px;\">\n                                    <button class=\"btn-blue btn-sm\" style=\"width:auto;padding:2px 7px;font-size:11px;\"\n                                            onclick=\"editProjectName('${s.id}','${esc(s.project_name)}')\">✏️</button>\n                                    <button class=\"btn-red btn-sm\" style=\"width:auto;padding:2px 7px;font-size:11px;background:#e53e3e;border-color:#e53e3e;\"\n                                            onclick=\"deleteProject('${s.id}','${esc(s.project_name)}')\">🗑️</button>\n                                    <button class=\"${s.status === 'active' ? 'btn-red' : 'btn-green'} btn-sm\"\n                                            style=\"width:auto;padding:2px 8px;font-size:11px;\"\n                                            onclick=\"toggleProject('${s.id}','${s.status}')\">\n                                        ${s.status === 'active' ? '🔴' : '🟢'}\n                                    </button>\n                                </div>\n                            </div>`).join('')\n                            : '<div style=\"color:var(--muted);font-size:12px;padding:4px 0 6px;\">No sub-projects yet.</div>'}\n                    </div>\n                </div>`;\n            }).join('');\n        }\n\n        async function adminAddMainActivity() {\n            const name = document.getElementById('newMainActivityName').value.trim();\n            if (!name) { showToast('⚠️ Enter category name'); return; }\n            showToast('⏳ Adding...');\n            try {\n                const res = await apiPost({ action: 'addActivity', activity_name: name, parent_id: '' });\n                if (res && res.status === 'ok') {\n                    document.getElementById('newMainActivityName').value = '';\n                    showToast('✅ Main activity added!');\n                    await bootApp();\n                    renderAdminPanel();\n                } else {\n                    showToast('⚠️ Add failed: ' + (res.error || 'unknown'));\n                }\n            } catch (e) {\n                showToast('⚠️ Connection error');\n                console.error(e);\n            }\n        }\n\n        async function adminAddSubActivity() {\n            const name     = document.getElementById('newSubActivityName').value.trim();\n            const parentId = document.getElementById('subActivityParent').value;\n            if (!name)     { showToast('⚠️ Enter sub-activity name'); return; }\n            if (!parentId) { showToast('⚠️ Select a parent activity'); return; }\n            showToast('⏳ Adding...');\n            try {\n                const res = await apiPost({ action: 'addActivity', activity_name: name, parent_id: parentId });\n                if (res && res.status === 'ok') {\n                    document.getElementById('newSubActivityName').value = '';\n                    showToast('✅ Sub-activity added!');\n                    await bootApp();\n                    renderAdminPanel();\n                } else {\n                    showToast('⚠️ Add failed: ' + (res.error || 'unknown'));\n                }\n            } catch (e) {\n                showToast('⚠️ Connection error');\n                console.error(e);\n            }\n        }\n\n        async function toggleActivity(id, curStatus) {\n            const ns = curStatus === 'active' ? 'inactive' : 'active';\n            await apiPost({ action: 'updateActivity', id, status: ns });\n            const d = await apiFetch('getActivities').catch(() => _activities);\n            if (Array.isArray(d)) _activities = d;\n            renderAdminActivities();\n            showToast(`✅ ${ns === 'active' ? 'Activated' : 'Deactivated'}!`);\n        }\n\n        async function editActivityName(id, cur) {\n            const n = prompt('Edit activity name:', cur);\n            if (!n || n.trim() === cur) return;\n            await apiPost({ action: 'updateActivity', id, activity_name: n.trim() });\n            const d = await apiFetch('getActivities').catch(() => _activities);\n            if (Array.isArray(d)) _activities = d;\n            renderAdminActivities();\n            showToast('✅ Activity renamed!');\n        }\n\n        async function deleteActivity(id, name) {\n            if (!confirm(`Are you sure you want to delete \"${name}\"?\\nThis will permanently delete this activity and all its sub-activities from the Google Sheet.`)) return;\n            showToast('⏳ Deleting...');\n            try {\n                const res = await apiPost({ action: 'deleteActivity', id });\n                if (res.error) {\n                    showToast('⚠️ Error: ' + res.error);\n                } else {\n                    showToast(`✅ Deleted activity and child dependencies!`);\n                    const d = await apiFetch('getActivities').catch(() => _activities);\n                    if (Array.isArray(d)) _activities = d;\n                    renderAdminActivities();\n                }\n            } catch (e) {\n                showToast('⚠️ Delete failed');\n            }\n        }\n\n        function renderAdminActivities() {\n            saveMasterCacheToStorage();\n            const el    = document.getElementById('adminActivityList');\n            if (!el) return;\n            const mains = _activities.filter(a => (!a.parent_id || String(a.parent_id).trim() === ''));\n            const parentSel = document.getElementById('subActivityParent');\n            if (parentSel) {\n                parentSel.innerHTML = '<option value=\"\">— Select Main Activity —</option>' +\n                    mains.filter(m => m.status === 'active')\n                         .map(m => `<option value=\"${m.id}\">${escHtml(m.activity_name)}</option>`).join('');\n            }\n            if (!mains.length) { el.innerHTML = '<p style=\"color:var(--muted);font-size:13px;text-align:center;padding:12px;\">No activities yet.</p>'; return; }\n            \n            // Clean HTML5 drag-and-drop template\n            el.innerHTML = mains.map(main => {\n                // String-safe .trim() comparison handles numeric ids (78) and string ids (\"78\") equally\n                const subs = _activities.filter(a => String(a.parent_id).trim() === String(main.id).trim());\n                const act  = main.status === 'active';\n                return `\n                <div draggable=\"true\" \n                     data-id=\"${main.id}\" \n                     ondragstart=\"dragStartActivity(event)\" \n                     ondragover=\"dragOverActivity(event)\" \n                     ondragend=\"dragEndActivity(event)\"\n                     ondrop=\"dropActivity(event)\" \n                     style=\"margin-bottom:12px;border:1.5px solid var(--border);border-radius:8px;overflow:hidden;cursor:move;transition:opacity 0.2s ease;\">\n                    <div style=\"background:#f8fafc;padding:10px 14px;display:flex;align-items:center;justify-content:space-between;gap:8px;\">\n                        <div>\n                            <span style=\"font-weight:700;font-size:14px;color:var(--primary);\">🔨 ${escHtml(main.activity_name)}</span>\n                            <span style=\"font-size:11px;margin-left:8px;color:${act ? '#38a169' : '#e53e3e'};\">${act ? '🟢' : '🔴'}</span>\n                        </div>\n                        <div style=\"display:flex;gap:6px;\">\n                            <button class=\"btn-blue btn-sm\" style=\"width:auto;padding:4px 8px;font-size:11px;\"\n                                    onclick=\"editActivityName('${main.id}','${esc(main.activity_name)}')\">✏️</button>\n                            <button class=\"btn-red btn-sm\" style=\"width:auto;padding:4px 8px;font-size:11px;background:#e53e3e;border-color:#e53e3e;\"\n                                    onclick=\"deleteActivity('${main.id}','${esc(main.activity_name)}')\">🗑️</button>\n                            <button class=\"${act ? 'btn-red' : 'btn-green'} btn-sm\"\n                                    style=\"width:auto;padding:4px 10px;font-size:11px;\"\n                                    onclick=\"toggleActivity('${main.id}','${main.status}')\">\n                                ${act ? '🔴 Off' : '🟢 On'}\n                            </button>\n                        </div>\n                    </div>\n                    <div style=\"padding:6px 14px 8px;\">\n                        ${subs.length\n                            ? subs.map(s => `\n                            <div style=\"display:flex;justify-content:space-between;align-items:center;padding:5px 0;border-bottom:1px solid #f1f5f9;\">\n                                <span style=\"font-size:13px;${s.status !== 'active' ? 'color:var(--muted);text-decoration:line-through;' : ''}\">↳ ${escHtml(s.activity_name)}</span>\n                                <div style=\"display:flex;gap:5px;\">\n                                    <button class=\"btn-blue btn-sm\" style=\"width:auto;padding:2px 7px;font-size:11px;\"\n                                            onclick=\"editActivityName('${s.id}','${esc(s.activity_name)}')\">✏️</button>\n                                    <button class=\"btn-red btn-sm\" style=\"width:auto;padding:2px 7px;font-size:11px;background:#e53e3e;border-color:#e53e3e;\"\n                                            onclick=\"deleteActivity('${s.id}','${esc(s.activity_name)}')\">🗑️</button>\n                                    <button class=\"${s.status === 'active' ? 'btn-red' : 'btn-green'} btn-sm\"\n                                            style=\"width:auto;padding:2px 8px;font-size:11px;\"\n                                            onclick=\"toggleActivity('${s.id}','${s.status}')\">\n                                        ${s.status === 'active' ? '🔴' : '🟢'}\n                                    </button>\n                                </div>\n                            </div>`).join('')\n                            : '<div style=\"color:var(--muted);font-size:12px;padding:4px 0 6px;\">No sub-activities yet.</div>'}\n                    </div>\n                </div>`;\n            }).join('');\n        }\n\n        // ── Materials ───────────────────────────────────────────────\n        async function adminAddMaterial() {\n            const name = document.getElementById('newMaterialName').value.trim();\n            const unit = document.getElementById('newMaterialUnit').value.trim();\n            if (!name) { showToast('⚠️ Enter material name'); return; }\n            showToast('⏳ Adding...');\n            try {\n                const res = await apiPost({ action: 'addMaterial', material_name: name, unit });\n                if (res && res.status === 'ok') {\n                    document.getElementById('newMaterialName').value = '';\n                    document.getElementById('newMaterialUnit').value = '';\n                    showToast('✅ Material added!');\n                    const d = await apiFetch('getMaterials').catch(() => _materials);\n                    if (Array.isArray(d)) _materials = d;\n                    renderAdminMaterials();\n                } else {\n                    showToast('⚠️ Add failed: ' + (res.error || 'unknown'));\n                }\n            } catch (e) {\n                showToast('⚠️ Connection error');\n                console.error(e);\n            }\n        }\n        window.adminAddMaterial = adminAddMaterial;\n\n        async function toggleMaterial(id, curStatus) {\n            const ns = curStatus === 'active' ? 'inactive' : 'active';\n            await apiPost({ action: 'updateMaterial', id, status: ns });\n            const d = await apiFetch('getMaterials').catch(() => _materials);\n            if (Array.isArray(d)) _materials = d;\n            renderAdminMaterials();\n            showToast(`✅ ${ns === 'active' ? 'Activated' : 'Deactivated'}!`);\n        }\n        window.toggleMaterial = toggleMaterial;\n\n        async function editMaterial(id, cur, curUnit) {\n            const n = prompt('Edit material name:', cur);\n            if (n === null) return;\n            const u = prompt('Edit default unit:', curUnit || '');\n            if (u === null) return;\n            await apiPost({ action: 'updateMaterial', id, material_name: n.trim(), unit: u.trim() });\n            const d = await apiFetch('getMaterials').catch(() => _materials);\n            if (Array.isArray(d)) _materials = d;\n            renderAdminMaterials();\n            showToast('✅ Material updated!');\n        }\n        window.editMaterial = editMaterial;\n\n        async function deleteMaterial(id, name) {\n            if (!confirm(`Delete material \"${name}\"? This cannot be undone.`)) return;\n            showToast('⏳ Deleting...');\n            try {\n                const res = await apiPost({ action: 'deleteMaterial', id });\n                if (res.error) { showToast('⚠️ Error: ' + res.error); return; }\n                showToast('✅ Deleted!');\n                const d = await apiFetch('getMaterials').catch(() => _materials);\n                if (Array.isArray(d)) _materials = d;\n                renderAdminMaterials();\n            } catch (e) {\n                showToast('⚠️ Delete failed');\n            }\n        }\n        window.deleteMaterial = deleteMaterial;\n\n        function renderAdminMaterials() {\n            saveMasterCacheToStorage();\n            const el = document.getElementById('adminMaterialList');\n            if (!el) return;\n            if (!_materials.length) { el.innerHTML = '<p style=\"color:var(--muted);font-size:13px;text-align:center;padding:12px;\">No materials yet.</p>'; return; }\n            el.innerHTML = _materials.map(m => {\n                const act = m.status !== 'inactive';\n                return `\n                <div style=\"display:flex;justify-content:space-between;align-items:center;padding:8px 0;border-bottom:1px solid var(--border);\">\n                    <div>\n                        <span style=\"font-size:13px;font-weight:600;${!act ? 'color:var(--muted);text-decoration:line-through;' : ''}\">${escHtml(m.material_name)}</span>\n                        <div style=\"font-size:11px;color:var(--muted);\">${m.unit ? 'Default unit: ' + escHtml(m.unit) : 'No default unit'}</div>\n                    </div>\n                    <div style=\"display:flex;gap:5px;\">\n                        <button class=\"btn-blue btn-sm\" style=\"width:auto;padding:2px 7px;font-size:11px;\"\n                                onclick=\"editMaterial('${m.id}','${esc(m.material_name)}','${esc(m.unit || '')}')\">✏️</button>\n                        <button class=\"btn-red btn-sm\" style=\"width:auto;padding:2px 7px;font-size:11px;background:#e53e3e;border-color:#e53e3e;\"\n                                onclick=\"deleteMaterial('${m.id}','${esc(m.material_name)}')\">🗑️</button>\n                        <button class=\"${act ? 'btn-red' : 'btn-green'} btn-sm\" style=\"width:auto;padding:2px 8px;font-size:11px;\"\n                                onclick=\"toggleMaterial('${m.id}','${m.status}')\">${act ? '🔴' : '🟢'}</button>\n                    </div>\n                </div>`;\n            }).join('');\n        }\n\n        // Project specific drag-and-drop (retained cleanly)\n        let _draggedId = null;\n\n        function dragStart(e) {\n            _draggedId = e.currentTarget.getAttribute('data-id');\n            e.dataTransfer.setData('text/plain', _draggedId);\n            e.dataTransfer.effectAllowed = 'move';\n        }\n\n        function dragOver(e) {\n            e.preventDefault();\n            e.dataTransfer.dropEffect = 'move';\n        }\n\n        async function dropProject(e) {\n            e.preventDefault();\n            const targetId = e.currentTarget.getAttribute('data-id');\n            if (!_draggedId || _draggedId === targetId) return;\n\n            const tops = _projects.filter(p => (!p.parent_id || String(p.parent_id).trim() === ''));\n            const draggedIdx = tops.findIndex(p => String(p.id).trim() === String(_draggedId).trim());\n            const targetIdx = tops.findIndex(p => String(p.id).trim() === String(targetId).trim());\n\n            if (draggedIdx !== -1 && targetIdx !== -1) {\n                const [moved] = tops.splice(draggedIdx, 1);\n                tops.splice(targetIdx, 0, moved);\n\n                const newOrder = [];\n                tops.forEach(top => {\n                    newOrder.push(String(top.id).trim());\n                    const subs = _projects.filter(p => String(p.parent_id).trim() === String(top.id).trim());\n                    subs.forEach(s => newOrder.push(String(s.id).trim()));\n                });\n                \n                const sortedProjects = [];\n                newOrder.forEach(id => {\n                    const found = _projects.find(p => String(p.id).trim() === String(id).trim());\n                    if (found) sortedProjects.push(found);\n                });\n                _projects = sortedProjects;\n                renderAdminProjects();\n                \n                await saveOrderToCloud('projects', newOrder);\n            }\n        }\n\n        // Clean HTML5 drag-and-drop state trackers for Activities module\n        let _draggedActivityId = null;\n\n        function dragStartActivity(e) {\n            _draggedActivityId = e.currentTarget.getAttribute('data-id');\n            e.dataTransfer.setData('text/plain', _draggedActivityId);\n            e.dataTransfer.effectAllowed = 'move';\n            e.currentTarget.style.opacity = '0.4';\n        }\n\n        function dragOverActivity(e) {\n            e.preventDefault();\n            e.dataTransfer.dropEffect = 'move';\n        }\n\n        function dragEndActivity(e) {\n            e.currentTarget.style.opacity = '1';\n        }\n\n        function dropActivity(e) {\n            e.preventDefault();\n            // data-id attribute is always a string — coerce both sides with String() for safe comparison\n            const targetId = String(e.currentTarget.getAttribute('data-id')).trim();\n            if (!_draggedActivityId || _draggedActivityId === targetId) return;\n\n            const mains = _activities.filter(a => !a.parent_id || String(a.parent_id).trim() === '');\n            // String-coerce both sides so numeric JSON ids match string data-id attributes\n            const draggedIdx = mains.findIndex(a => String(a.id).trim() === String(_draggedActivityId).trim());\n            const targetIdx  = mains.findIndex(a => String(a.id).trim() === String(targetId).trim());\n\n            if (draggedIdx === -1 || targetIdx === -1) {\n                console.warn('dropActivity: could not find dragged or target item in mains list', { _draggedActivityId, targetId });\n                return;\n            }\n\n            // Re-order mains array in memory\n            const [moved] = mains.splice(draggedIdx, 1);\n            mains.splice(targetIdx, 0, moved);\n\n            // Build flat ordered ID list: each main followed by its subs\n            const newOrder = [];\n            mains.forEach(main => {\n                newOrder.push(String(main.id));\n                _activities\n                    .filter(a => String(a.parent_id).trim() === String(main.id).trim())\n                    .forEach(s => newOrder.push(String(s.id)));\n            });\n\n            // Reconstruct _activities in the new sequence (string-safe find)\n            const sortedActivities = [];\n            newOrder.forEach(id => {\n                const found = _activities.find(a => String(a.id).trim() === id);\n                if (found) sortedActivities.push(found);\n            });\n            _activities = sortedActivities;\n\n            // Instant local re-render — UI is authoritative\n            renderAdminActivities();\n\n            // Fire-and-forget background sync\n            saveActivityOrderDirect(newOrder);\n        }\n\n        function saveActivityOrderDirect(orderedIds) {\n            // Always send the flat ordered-id string array the backend expects.\n            // orderedIds[0] → sort_order 1, orderedIds[1] → sort_order 2, etc.\n            const directUrl = 'https://script.google.com/macros/s/AKfycbzyjSPIlewC31HdvS0LQneOudT-gQ1h-qCs_1q_50U47nej9zGSFRyaW7QI91yvVk1PEw/exec';\n            const payload = {\n                action:     'updateSortOrder',\n                type:       'activities',\n                orderedIds: orderedIds.map(id => String(id))   // normalise to strings before sending\n            };\n\n            console.info('[ActivitySync] Firing background sort commit →', JSON.stringify(payload));\n\n            // mode:'no-cors' → opaque response, fetch promise ALWAYS resolves,\n            // never rejects on HTTP errors. UI is already authoritative; we never\n            // show a toast or alert from this background transaction.\n            fetch(directUrl, {\n                method:  'POST',\n                mode:    'no-cors',\n                headers: { 'Content-Type': 'text/plain;charset=utf-8' },\n                body:    JSON.stringify(payload)\n            })\n            .then(() => {\n                console.info('[ActivitySync] Background sort commit handshake resolved (opaque — verify in Apps Script execution log).');\n            })\n            .catch(err => {\n                console.warn('[ActivitySync] Network proxy metadata (non-blocking):', err);\n            });\n        }\n\n        // Shared/Projects network sync\n        async function saveOrderToCloud(type, orderedIds) {\n            console.log(`Optimistic Update Triggered: Syncing sorted ${type} order to cloud in the background...`);\n            const payload = {\n                action: 'updateSortOrder',\n                type: type,\n                orderedIds: orderedIds\n            };\n            console.log(\"Reordering Sync Payload:\", JSON.stringify(payload));\n            \n            fetch(SHEET_URL, {\n                method: 'POST',\n                headers: {\n                    'Content-Type': 'text/plain;charset=utf-8'\n                },\n                body: JSON.stringify(payload)\n            })\n            .then(async (response) => {\n                if (!response.ok) {\n                    throw new Error(`HTTP status ${response.status}`);\n                }\n                const resText = await response.text();\n                console.log('Background sort order sync raw response text:', resText);\n                \n                const t = document.getElementById('toast');\n                if (t) {\n                    t.classList.remove('show');\n                    t.textContent = '';\n                    clearTimeout(t._tid);\n                }\n            })\n            .catch(err => {\n                console.warn('Background sort order sync failed silently (optimistic UI remains active):', err);\n            });\n        }\n\n        if (typeof window !== \"undefined\") {\n            window.dragStart = dragStart;\n            window.dragOver = dragOver;\n            window.dropProject = dropProject;\n            window.dropActivity = dropActivity;\n            window.dragStartActivity = dragStartActivity;\n            window.dragOverActivity = dragOverActivity;\n            window.dragEndActivity = dragEndActivity;\n        }\n\n        // Read-only accessors for the portal-mounted React components\n        // (AnalyticsDashboard, DprEntryForm, HistoryScreen, MaterialsScreen) to read the same in-memory arrays without duplicating fetch logic.\n        window.__getHistory  = function() { return _history; };\n        window.__getProjects = function() { return _projects; };\n        window.__getMaterials = function() { return _materials; };\n        window.__getActivities = function() { return _activities; };\n        window.__getCurrentUser = function() { return _currentUser; };\n        window.__getUsers = function() { return _users; };\n        window.__getHistoryStatus = function() { return _historyStatus; };\n        window.__getMaterialLogs = function() { return _materialLogs; };\n        window.__getMaterialLogsStatus = function() { return _materialLogsStatus; };\n\n        /* ═══════════════════════════════════════════════════════════\n           DASHBOARD — now a real React component, see\n           /components/dashboard/AnalyticsDashboard.jsx, portal-mounted\n           into #__dashboard_mount__. window.__getHistory()/__getProjects()\n           above and the 'dpr:historyUpdated'/'dpr:themeChanged' events\n           are the interop bridge.\n        ═══════════════════════════════════════════════════════════ */\n\n        /* ═══════════════════════════════════════════════════════════\n           WINDOW EXPORTS (for onclick= handlers in HTML)\n        ═══════════════════════════════════════════════════════════ */\n\n        /* ══ INIT ══ */\n        if (typeof window !== \"undefined\") {\n            const runInit = () => {\n                updateThemeToggleIcon();\n                renderLoginChips();\n                restoreSession();\n\n                window.addEventListener('offline', () => { document.getElementById('offlineBadge').style.display = 'block'; });\n                window.addEventListener('online', () => { document.getElementById('offlineBadge').style.display = 'none'; syncOfflineQueue(); });\n                if (!navigator.onLine) document.getElementById('offlineBadge').style.display = 'block';\n            };\n\n            if (document.readyState === 'complete' || document.readyState === 'interactive') {\n                runInit();\n            } else {\n                window.addEventListener('load', runInit);\n            }\n\n        }";
    document.body.appendChild(appScript);

    // -- Bootstrap: login-screen name chips. The session itself is
    //    restored by the app script's restoreSession() (cookie-based). --
    setTimeout(() => {
      if (typeof fetchUsersFromCloud === 'function') fetchUsersFromCloud();
    }, 600);

  }, []);

  return (<><div id="__dpr_root__" /><AnalyticsDashboard /><DprEntryForm /><HistoryScreen /><MaterialsScreen /></>);
}
